class Solution {
  public int findMaxVal(int n, int[][] restrictions, int[] diff) {
    int INF = Integer.MAX_VALUE / 2;
    int[] ub = new int[n];
    java.util.Arrays.fill(ub, INF);
    for (int[] r : restrictions) ub[r[0]] = Math.min(ub[r[0]], r[1]);
    ub[0] = 0;
    for (int i = 1; i < n; i++) ub[i] = Math.min(ub[i], ub[i - 1] + diff[i - 1]);
    for (int i = n - 2; i >= 0; i--) ub[i] = Math.min(ub[i], ub[i + 1] + diff[i]);
    int best = 0;
    for (int v : ub) best = Math.max(best, v);
    return best;
  }
}
